window.ScripturaLexicons.BDAG_PART_0093 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dotheis-bdag\" data-source=\"BDAG\" data-search=\"δοθείς dotheís forma remissiva ver δίδωμι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δοθείς</td><td>forma remissiva</td><td>ver δίδωμι</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-doi-bdag\" data-source=\"BDAG\" data-search=\"δοῖ doî forma remissiva ver δίδωμι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δοῖ</td><td>forma remissiva</td><td>ver δίδωμι</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dokeo-bdag\" data-source=\"BDAG\" data-search=\"δοκέω dokéō verbo pensar; parecer; decidir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δοκέω</td><td>verbo</td><td>pensar; parecer; decidir</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dokimazo-bdag\" data-source=\"BDAG\" data-search=\"δοκιμάζω dokimázō verbo examinar; pôr à prova; aprovar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δοκιμάζω</td><td>verbo</td><td>examinar; pôr à prova; aprovar</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dokimasia-bdag\" data-source=\"BDAG\" data-search=\"δοκιμασία, ας, ἡ dokimasía substantivo feminino prova; exame; verificação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δοκιμασία, ας, ἡ</td><td>substantivo feminino</td><td>prova; exame; verificação</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dokime-bdag\" data-source=\"BDAG\" data-search=\"δοκιμή, ῆς, ἡ dokimḗ substantivo feminino prova; caráter comprovado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δοκιμή, ῆς, ἡ</td><td>substantivo feminino</td><td>prova; caráter comprovado</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dokimion-bdag\" data-source=\"BDAG\" data-search=\"δοκίμιον, ου, τό dokímion substantivo neutro prova; autenticidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δοκίμιον, ου, τό</td><td>substantivo neutro</td><td>prova; autenticidade</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dokimos-bdag\" data-source=\"BDAG\" data-search=\"δόκιμος, ον dókimos adjetivo aprovado; estimado; precioso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δόκιμος, ον</td><td>adjetivo</td><td>aprovado; estimado; precioso</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dokos-bdag\" data-source=\"BDAG\" data-search=\"δοκός, οῦ, ἡ dokós substantivo feminino viga; trave BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δοκός, οῦ, ἡ</td><td>substantivo feminino</td><td>viga; trave</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dolios-bdag\" data-source=\"BDAG\" data-search=\"δόλιος, ία, ον dólios adjetivo enganoso; traiçoeiro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δόλιος, ία, ον</td><td>adjetivo</td><td>enganoso; traiçoeiro</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-doliotes-bdag\" data-source=\"BDAG\" data-search=\"δολιότης, ητος, ἡ doliótēs substantivo feminino engano; traição BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δολιότης, ητος, ἡ</td><td>substantivo feminino</td><td>engano; traição</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dolioo-bdag\" data-source=\"BDAG\" data-search=\"δολιόω dolióō verbo enganar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δολιόω</td><td>verbo</td><td>enganar</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dolos-bdag\" data-source=\"BDAG\" data-search=\"δόλος, ου, ὁ dólos substantivo masculino engano; ardil; traição BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δόλος, ου, ὁ</td><td>substantivo masculino</td><td>engano; ardil; traição</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-doloo-bdag\" data-source=\"BDAG\" data-search=\"δολόω dolóō verbo falsificar; adulterar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δολόω</td><td>verbo</td><td>falsificar; adulterar</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-doma-bdag\" data-source=\"BDAG\" data-search=\"δόμα, δόματος, τό dóma substantivo neutro dádiva; presente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δόμα, δόματος, τό</td><td>substantivo neutro</td><td>dádiva; presente</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-doxa-bdag\" data-source=\"BDAG\" data-search=\"δόξα, ης, ἡ dóxa substantivo feminino glória; esplendor; honra; fama BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δόξα, ης, ἡ</td><td>substantivo feminino</td><td>glória; esplendor; honra; fama</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-doxazo-bdag\" data-source=\"BDAG\" data-search=\"δοξάζω doxázō verbo louvar; honrar; glorificar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δοξάζω</td><td>verbo</td><td>louvar; honrar; glorificar</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-doxologia-bdag\" data-source=\"BDAG\" data-search=\"δοξολογία, ας, ἡ doxología substantivo feminino cântico de louvor; oração BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δοξολογία, ας, ἡ</td><td>substantivo feminino</td><td>cântico de louvor; oração</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dorkas-bdag\" data-source=\"BDAG\" data-search=\"Δορκάς, άδος, ἡ Dorkás nome próprio feminino Dorcas; gazela BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Δορκάς, άδος, ἡ</td><td>nome próprio feminino</td><td>Dorcas; gazela</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dory-bdag\" data-source=\"BDAG\" data-search=\"δόρυ, ρατος, τό dóry substantivo neutro lança BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δόρυ, ρατος, τό</td><td>substantivo neutro</td><td>lança</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article id=\"entry-dotheis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δοθείς</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dotheís⟧</span><span class=\"separator\">·</span><span>forma remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Ver δίδωμι.</div></section></article> <article id=\"entry-doi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δοῖ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦doî⟧</span><span class=\"separator\">·</span><span>forma remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Ver δίδωμι.</div></section></article> <article id=\"entry-dokeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δοκέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dokéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Imperfeito ἐδόκουν, terceira pessoa do plural ἐδοκοῦσαν, Hs 9, 9, 5 (ver B-D-F §84, 3); futuro δόξω; primeiro aoristo ἔδοξα; perfeito passivo, terceira pessoa do singular, δέδοκται, 1Esd 8:11; particípio δεδογμένον, LXX (ver δόγμα; Homero e posteriores).\n<p><strong>① Considerar algo provável: pensar, crer, supor, julgar.</strong> Transitivo, exprimindo opinião subjetiva (Homero e posteriores; papiros; raro na LXX).\n<strong>ⓐ Seguido de infinitivo cujo sujeito coincide com o do verbo principal</strong> (Xenofonte, An. 2, 2, 14; Diodoro Sículo 17, 27, 2, τοὺς δοκοῦντας νενικηκέναι; Pv 28:24; 4Mac 13:14; Justino, D. 2, 4, δοκεῖς κατόψεσθαι): μὴ δόξητε λέγειν, «não suponhais que deveis dizer», Mt 3:9; ἐδόκουν πνεῦμα θεωρεῖν, «pensavam estar vendo um espírito», Lc 24:37; ὸ̔ δοκεῖ ἔχειν, «aquilo que pensa possuir», Lc 8:18 (cf. Josefo, Bell. 3, 319); ὁ δοκῶν πνεῦμα ἔχειν, «aquele que pensa ter o Espírito», Hm 11:12; cf. Jo 5:39; 16:2; At 27:13; 1Co 7:40; Fp 3:4; Tg 1:26; 2Cl 17:3; Dg 3:5; 8:10; Hm 10, 2, 4.\n<strong>ⓑ Seguido de infinitivo com nominativo</strong>: ὅσῳ δοκεῖ μᾶλλον μείζων εἶναι, «quanto maior ele pensa ser» (ou «parece ser», ver ②), 1Cl 48:6; εἴ τις δοκεῖ σοφὸς εἶναι, «se alguém pensa ser sábio», 1Co 3:18; εἴ τις δοκεῖ προφήτης εἶναι, 1Co 14:37; εἴ τις δοκεῖ φιλόνεικος εἶναι, «se alguém está inclinado a contender», 1Co 11:16; Gl 6:3.\n<strong>ⓒ Seguido de acusativo e infinitivo com sujeitos diferentes</strong> (Xenofonte, An. 1, 7, 1; PTebt 413, 6, μὴ δόξῃς με, κυρία, ἠμεληκέναι σου τῶν ἐντολῶν; Gn 38:15; 2Mac 7:16; 3Mac 5:5; Demétrio: 722, frag. 1, 1 Jac.; Josefo, Ant. 2, 340; Justino, A I, 3, 1; D. 118, 2): μή τίς με δόξῃ ἄφρονα εἶναι, «ninguém me considere insensato», 2Co 11:16; ἃ δοκοῦμεν ἀτιμότερα εἶναι, «[membros do corpo] que consideramos menos dignos de atenção especial», 1Co 12:23.\n<strong>ⓓ Seguido de ὅτι</strong> (Arriano, Alex. An. 4, 28, 2): Mt 6:7; 26:53; Mc 6:49; Lc 12:51; 13:2, 4; Jo 5:45; 11:13, 31; 1Co 4:9, variante; 2Co 12:19; Tg 4:5; Hv 4, 3, 7; 5:3.\n<strong>ⓔ Emprego parentético</strong> (B-D-F §465, 2; Rob. 434; cf. Anacreontea 35, 15 Preis., πόσον δοκεῖς πονοῦσιν; Aristófanes, Acharn. 12; Epicteto 2, 19, 7; POxy 1218, 6s., ἡ μήτηρ μου Θαῆσις εἰς Ἀντινόου, δοκῶ, ἐπὶ κηδίαν ἀπῆλθεν): πόσῳ δοκεῖτε χείρονος ἀξιωθήσεται τιμωρίας;, «quanto mais severamente, pensais vós, será ele punido?», Hb 10:29; τί δοκεῖτε ποιήσει;, «que fará ele, em vossa opinião?», Hs 9, 28, 8; cf. 1Co 4:9; οὔ, δοκῶ, «suponho que não», Lc 17:9, variante.\n<strong>ⓕ Emprego elíptico</strong> (2Mac 2:29): ᾗ οὐ δοκεῖτε ὥρᾳ ὁ υἱὸς τ. ἀνθρώπου ἔρχεται, «o Filho do Homem virá numa hora em que não pensais [que virá]», Mt 24:44; cf. Lc 12:40; τί δοκεῖτε;, «que pensais?», 1Cl 43:6; 2Cl 7:5; τί δοκεῖς τοὺς κεκλημένους;, «que pensas dos que foram chamados?», Hs 9, 14, 5 (cf. Xenofonte, An. 5, 7, 26, τούτους τί δοκεῖτε;).</p>\n<p><strong>② Apresentar-se ao entendimento de alguém: parecer, ser reconhecido como tal.</strong>\n<strong>ⓐ Intransitivo</strong> (Homero e outros; assim na maior parte da LXX).\n<strong>α. Ter aparência</strong>, com dativo de pessoa: τίς τούτων … πλησίον δοκεῖ σοι γεγονέναι;, «qual destes, na tua opinião, mostrou ser o próximo?», Lc 10:36 (sobre τίνα … δοκεῖς … γεγονέναι;, variante, cf. ①ⓒ); δ. καταγγελεὺς εἶναι, «ele parece ser pregador», At 17:18; cf. 1Co 12:22; 2Co 10:9; Hb 12:11; Dg 8:10 (παρὰ πᾶσι σπέρματα ἀληθείας δοκεῖ εἶναι, Justino, A I, 44, 10). εἴ τινι μὴ δοκοίη κἂν ταῦτα ἱκανά, «se mesmo isso parecer insuficiente a alguém», Dg 2:10 (cf. Justino, D. 42, 4); οὐδέν μοι δοκοῦσι διαφέρειν, «parecem-me não diferir em nada», Dg 3:5 (παράδοξον λέγειν μοι δοκεῖς, Justino, D. 49, 6). ἔδοξα ἐμαυτῷ δεῖν πρᾶξαι, equivalente ao latim <i>mihi videbar</i>, «estava convencido de que precisava agir», At 26:9 (cf. Aristófanes, Vesp. 177, 1265; Ésquines 3, 53 [Schwyzer II, 193]); GMary 463, 9. τὸ δοκεῖν, «na aparência [somente]» (Sexto 64; Sb 7696, 55 [250 d.C.]; Josefo, Vi. 75; Ant. 14, 291, variante de τῷ δοκεῖν; ver Hdb. sobre ITr 10), ITr 10; ISm 2; 4:2. ὁ δοκῶν ἐνθάδε θάνατος, «aquilo que neste mundo parece ser morte», Dg 10:7 (τὰ δοκούντα καλά, Justino, A II, 1, 6; τῶν ἐν βαρβάροις … δοξάντων σοφῶν, A I, 7, 3). Como expressão que atenua uma afirmação, Hb 4:1.\n<strong>β. Ter influência, ser reconhecido como alguém importante, gozar de reputação</strong> (cf. Sus 5; 2Mac 1:13): οἱ δοκοῦντες, «homens influentes» (Eurípides, Hec. 295; Petosíris, frag. 6, linha 58, οἱ δ. = «os dignitários proeminentes»; Herodiano 6, 1, 2; Josefo, C. Ap. 1, 67), Gl 2:2, 6b. Expressão mais desenvolvida de mesmo sentido, com infinitivo adicional (Xenofonte, Cyr. 7, 1, 41; Platão, Gorg. 472a, Euthd. 303c, οἱ δοκοῦντες εἶναί τι; Plutarco, Mor. 212b, δοκοῦντας εἶναί τινας; Epicteto, Ench. 33, 12; Herodiano 4, 2, 5; Fílon, Mos. 2, 241), Gl 2:6a, 9 (Platão, Apol. 6, 21b, οἱ δοκοῦντες σοφοὶ εἶναι). WFoerster, «D. δοκοῦντες in Gal 2», ZNW 36, 1938, 286–292 (contra ele, HGreeven, ZNW 44, 1952, 41, n. 100). οἱ δοκοῦντες ἄρχειν, «os que têm reputação de governantes», Mc 10:42 (cf. Plutarco, Arat. 1047 [43, 2], ᾧ δουλεύουσιν οἱ δοκοῦντες ἄρχειν).</p>\n<p><strong>ⓑ Impessoal: δοκεῖ μοι, «parece-me»</strong> (Élio Aristides 47, p. 427 D., ἔμοιγε δοκεῖ; Josefo, Ant. 6, 227, δοκεῖ σοι; Justino, D. 5, 2, οὕτως δοκεῖ ὀρθῶς ἔχειν).\n<strong>α. Penso, creio</strong> (cf. ①): τί σοι δοκεῖ;, «que te parece?», Mt 17:25; 22:17; τί ὑμῖν δοκεῖ;, Mt 18:12; 21:28; 26:66; Jo 11:56. Seguido de περί τινος (Luciano, Dial. Deor. 6, 4), Mt 22:42; GMary 463, 6 (PRyl 3, 463). Com acusativo e infinitivo (Élio Aristides 46, p. 344 D.), οὐ δοκεῖ σοι τὸ μετανοῆσαι σύνεσιν εἶναι;, «não te parece que arrependimento é compreensão?», Hm 4, 2, 2; cf. m 8:6; 11; 10, 1, 2. τὸ δοκοῦν τινι, «o arbítrio de alguém» (Diodoro Sículo 19, 91, 1, αὐτῷ τὸ δοκοῦν = «seu próprio arbítrio»; Justino, A II, 14, 1, τὸ ὑμῖν δοκοῦν); κατὰ τὸ δ. αὐτοῖς, «segundo o arbítrio deles» (Luciano, Tim. 25; cf. Tucídides 1, 84, 2, παρὰ τὸ δοκοῦν ἡμῖν), Hb 12:10.\n<strong>β. Parece-me melhor: decido, resolvo</strong>, seguido de infinitivo (Xenofonte, An. 1, 10, 17; Diodoro Sículo 18, 55, 2; Apiano, Iber. 63 §265; SIG 1169, 77 [séc. IV a.C.]; Josefo, Ant. 6, 321), Lc 1:3 (estilo de decreto; cf. as passagens seguintes). Como termo técnico administrativo (frequente em inscrições, p.ex. IPriene 105, 20 [9 a.C.]), At 15:22, 25, 28 (cf. Josefo, Ant. 16, 163, ἔδοξέ μοι κ. τῷ ἐμῷ συμβουλίῳ … χρῆσθαι; Díon Crisóstomo 80 [30], 8, ἔδοξε τῷ θεῷ; sobre implicações socioculturais das passagens de Atos, ver Ferguson, <i>Legal Terms</i>, 50–53; Danker, <i>Benefactor</i>, 310–313; também MSimon, BJRL 52, 1969/70, 437–460; CPerrot, RSR 69, 1981, 195–208); ἄλογον γάρ μοι δοκεῖ, «julguei isso desarrazoado», At 25:27; cf. MPol 12:3. ὡς ἄν σοι δόξῃ, «conforme te parecer melhor», D 13:7 (Arriano, Cyneg. 3, 4, ὥς μοι δοκεῖ).</p>\n<p>Compare-se o contraste entre os dois sentidos: τὰ ἀεὶ δοκοῦντα … τῷ δοκοῦντι εἶναι ἀληθῆ, «o que parece verdadeiro é verdadeiro para quem assim pensa», Platão, Tht. 158e (ver L-S-J-M, δ., final). — EHamp, ClPh 63, 1968, 285–287. — B. 1121. DELG. Schmidt, <i>Syn.</i> I, 321–328, ver δόξα. M-M. EDNT. TW. Sv.</p></div></section></article> <article id=\"entry-dokimazo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δοκιμάζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dokimázō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Ver os quatro verbetes seguintes.) Futuro δοκιμάσω, δοκιμῶ na LXX; primeiro aoristo ἐδοκίμασα; perfeito, segunda pessoa do singular, δεδοκίμακας, Jr 12:3; passivo δεδοκίμασμαι (Heródoto, Tucídides e posteriores).\n<p><strong>① Submeter algo a exame crítico para averiguar sua autenticidade: pôr à prova, examinar.</strong> (Assim geralmente na LXX; EpArist 276; Josefo, Ant. 1, 233; 3, 15; TestAsh 5:4; Taciano, Ath.; Irineu 1, prólogo 2 [Harv. I, 3, 9].) Com acusativo, testar bois quanto à utilidade, Lc 14:19 (Heródoto 2, 38, a respeito dos touros Ápis). ἑαυτόν, «examinar a si mesmo», 1Co 11:28; 2Co 13:5; a própria obra, Gl 6:4; as obras de Deus, Hb 3:9, variante (Sl 94:9); o próprio Deus (com πειράζω), ApcPt (Ox 849, 25); τὰ διαφέροντα, Rm 2:18; Fp 1:10; φθοριμαίοις (no códice, φθοριμειοις) λόγοις, οὓς σὺ (no códice, σοι) δοκίμασον, «afirmações destrutivas que deves avaliar», AcPlCor 1:3; todas as coisas, 1Ts 5:21; espíritos (dos falsos profetas), 1Jo 4:1; cf. D 12:1; Hm 11, 7, 16; 1Cl 42:4; os fiéis em geral, Hs 8, 2, 5; figuradamente οἰκοδομήν, «construção», Hs 9, 5, 2; céu e terra, Lc 12:56a; τὸν καιρόν, «o tempo», v. 56b; convencer-se da fidelidade de alguém, 1Cl 1:2; tentar descobrir τί ἐστιν εὐάρεστον τῷ κυρίῳ, «o que agrada ao Senhor», Ef 5:10. — Do exame de candidatos ao serviço especial na comunidade cristã (segundo o uso ático: Lísias 16, 3; Platão, Leg. 6, 765c; inscrições áticas), 1Tm 3:10. De Deus, 1Ts 2:4b (Jr 11:20; 17:10; 20:12; Sl 7:10; 26:2; Josefo, Ant. 1, 233). — De adversários: Βαρσαββὰς … δοκιμαζόμενος ὑπὸ τῶν ἀπίστων, «Barsabás … era submetido à prova pelos incrédulos», Pápias (11:2). — Quanto a Rm 2:18 e 12:2, ver ②ⓑ.</p>\n<p><strong>② Chegar a uma conclusão acerca do valor de algo com base em prova: comprovar, aprovar.</strong> O enfoque recai aqui sobre o resultado do procedimento ou exame.\n<strong>ⓐ Comprovar por meio de prova</strong>, a respeito de ouro (Isócrates, Panathen. 14, 39; SIG 334, 45 [quanto à associação monetária, ver outras referências em SEG XLII, 1851]; Pv 8:10; Sir 2:5; Sb 3:6), 1Pe 1:7 (sobre prova do caráter, cf. Píndaro, P. 10, 67s.); Hv 4, 3, 4; cf. 1Co 3:13 (JGnilka, <i>Ist 1 Cor 3:10–15 ein Schriftzeugnis für d. Fegefeuer?</i>, 1955). τὰς ψυχάς, «as almas», ApcPt 3.\n<strong>ⓑ Aceitar como comprovado: aprovar</strong> (PEleph 1, 10; POxy 928, 7, ἵνα ἐὰν δοκιμάσῃς ποιήσῃς; PTebt 326, 10). Com acusativo, τὶ, ISm 8:2; οὓς ἐὰν δοκιμάσητε, «os que julgardes qualificados», 1Co 16:3; ἐδοκιμάσαμεν σπουδαῖον ὄντα, «nós o examinamos e o consideramos zeloso», 2Co 8:22; ἐδοκίμασε γὰρ ὑμᾶς ὁ κύριος καὶ ἐνέγραψεν ὑμᾶς εἰς τὸν ἀριθμὸν τὸν ἡμέτερον, «pois o Senhor vos aprovou e vos inscreveu em nosso número», Hs 9, 24, 4; cf. λίθους, v 3, 5, 3. δ. τὸ ἀγάπης γνήσιον, «comprovar a genuinidade do amor», 2Co 8:8; ἐν ᾧ δοκιμάζει, «naquilo que ele aprova», Rm 14:22; δ. τὰ διαφέροντα, «aprovar [ou descobrir, ver ①] o que é essencial», Rm 2:18; Fp 1:10. Seguido de infinitivo (Apiano, Iber. 90 §392; Bell. Civ. 2, 114 §475; Josefo, Ant. 2, 176; Vi. 161, simplesmente «pretender, desejar»): οὐκ ἐδοκίμασαν τὸν θεὸν ἔχειν ἐν ἐπιγνώσει, «não julgaram conveniente conservar o verdadeiro conhecimento de Deus», Rm 1:28 (antecipando o contraste com Rm 12:2; WReiss, «Gott nicht kennen» im AT, ZAW 58, 1940/41, 70–98). Seguido de interrogação indireta: δ., τί τὸ θέλημα τ. θεοῦ, «aprovar [ou descobrir, ver ①] qual é a vontade de Deus», Rm 12:2. Na passiva (Prov. Aesopi 171 P., φίλος καὶ ἵππος ἐν ἀνάγκῃ δοκιμάζονται, «amigo e cavalo são provados na necessidade»; Josefo, Ant. 3, 71): δεδοκιμάσμεθα, «fomos considerados dignos», seguido de infinitivo, 1Ts 2:4a. δεδοκιμασμένος, «testado, aprovado», de profetas autênticos, D 11:11 (Diodoro Sículo 4, 7, 1, δεδοκιμασμένος, do narrador renomado; cf. SIG 807, 9; PFay 106, 23; 2Mac 4:3); cf. Hm 11, 7, 16 (ver ①); πνεῦμα δεδοκιμασμένον, v 2, 4; de Jesus, At 2:22, códice D. — B. 652. DELG, s.v. δοκάω etc. EDNT. M-M. TW. Spicq.</p></div></section></article> <article id=\"entry-dokimasia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δοκιμασία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dokimasía⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Ver δοκιμάζω, δοκιμή, δοκίμιον, δόκιμος; Lísias e outros; Políbio, Plutarco, Epicteto; SIG 972, 29; PSI 1105, 18 [séc. II d.C.]; PMert 26, 11 [séc. III d.C.]; PLeid X vii, 12; 20; ix, 12; Sir 6:21; PsSol 16:14; TestSol 19:3 P.; Josefo, Ant. 4, 54.) <strong>Exame destinado a verificar a autenticidade: prova, teste, exame.</strong> πειράζειν ἐν δ., «submeter à prova», Hb 3:9; πύρωσις τῆς δ., «prova pelo fogo», D 16:5. — M-M. TW. Spicq. Sv.</div></section></article> <article id=\"entry-dokime-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δοκιμή, ῆς, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dokimḗ⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Ver δοκιμάζω, δοκίμιον e δόκιμος; diversos manuscritos de Dioscórides, <i>Mater. Med.</i> 4, 184 Wellm. II, p. 333, 9, nota; Achmes 24, 9; Cat. Cod. Astr. X, 67, 7; Sl 67:31, Símaco. — B-D-F §110, 2; Mlt-H. 352.)<p><strong>① Processo de pôr à prova: teste, provação.</strong> (Sexto 7a, δ. πίστεως.) ἐν πολλῇ δοκιμῇ θλίψεως, «em grande provação de aflição», 2Co 8:2.</p><p><strong>② Experiência de passar por uma prova, com especial atenção ao resultado: resistência comprovada à prova, caráter aprovado.</strong> Rm 5:4 (construção de sentido concentrado: ὑπομονή, como processo de suportar alguma coisa, equivale a uma prova que desenvolve e confirma o caráter de quem a enfrenta; esse resultado bem-sucedido, por sua vez, promove ἐλπίς). γινώσκειν τὴν δ. τινος, «determinar a disposição de alguém», 2Co 2:9; «comprovar o caráter ou valor de alguém», Fp 2:22. δ. τῆς διακονίας, «o caráter aprovado do vosso serviço», 2Co 9:13. — δ. ζητεῖν, «desejar prova ou evidência», 2Co 13:3. — M-M. TW. Spicq.</p></div></section></article> <article id=\"entry-dokimion-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δοκίμιον, ου, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dokímion⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Ver os três verbetes anteriores e δόκιμος; sobre a grafia, Mlt-H. 78; B-D-F §23; B-D-R §§13, 3; 263, 5; a forma δοκιμεῖον é preferida por PKatz, TLZ 83, 1958, 314s.; WGrundmann, TW II, 259.)<p><strong>① Processo ou meio de determinar a genuinidade de algo: prova, meio de comprovação.</strong> (Dionísio de Halicarnasso, Rhet. 11, 1; Herodiano 2, 10, 6; Plutarco, Mor. 230b; Περὶ ὕψους 32, 5, γλῶσσα γεύσεως δοκίμιον, «a língua é o meio de testar o sabor»; Pv 27:21.) τὸ δ. ὑμῶν τῆς πίστεως κατεργάζεται ὑπομονήν, «a prova da vossa fé [tentação] produz perseverança», Tg 1:3.</p><p><strong>② Genuinidade como resultado de uma prova: autêntico, sem mistura</strong>, neutro singular do adjetivo δοκίμιος (especialmente de metais: BGU 1045 II, 12; 1065, 8; PTebt 392, 22; ver Dssm., NB 86ss. [BS 259ss.]). τὸ δ. ὑμῶν τῆς πίστεως, «a autenticidade da vossa fé» (sobre o uso, B-D-F §263, 2), 1Pe 1:7 (δόκιμον em P⁷² e outros; cf. Tg 1:3, variante; ver δόκιμος ①). — DELG, s.v. δοκάω etc., III, p. 291. M-M. TW. Spicq.</p></div></section></article> <article id=\"entry-dokimos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δόκιμος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dókimos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Ver os quatro verbetes anteriores; pré-socráticos, Heródoto e posteriores; superlativo em Taciano 1, 1; 38, 1.) CArbenz, <i>Die Adjektiva auf -ιμος</i>, diss., Zurique, 1933, 38ss.; Schwyzer I, 494s.<p><strong>① Genuíno por ter sido submetido à prova: aprovado, experimentado, autêntico.</strong> (Alceu 6, 12 L-P [119 + 120 + 122 Diehl], de um homem: νῦν τις ἀνὴρ δόκιμος γενέσθω, «mostre-se agora alguém um homem aprovado»; TestJos 2:7.) Tg 1:12; 2Co 10:18; 13:7; 2Tm 2:15. δ. τραπεζῖται, «cambistas aprovados» (que põem em circulação dinheiro autêntico ou de curso legal [cf. Epicteto 1, 7, 6, δραχμὰς δοκίμους κ. ἀδοκίμους; Sócrates, Ep. 6, 12]), Agr 11. ὁ δ. ἐν Χριστῷ, «aquele que é aprovado em Cristo», isto é, «o cristão experimentado e fiel», Rm 16:10; οἱ δ., 1Co 11:19.</p><p><strong>② Considerado digno de elevada consideração: respeitado, estimado.</strong> (Heródoto e outros; Fílon, Op. M. 128, De Jos. 201; Josefo, C. Ap. 1, 18.) δ. τοῖς ἀνθρώποις, «estimado entre os homens» (em contraste com Deus), Rm 14:18.</p><p><strong>③ Valioso, precioso.</strong> Comparativo aplicado aos ossos de Policarpo, «mais preciosos que ouro» (cf. 1Pe 1:7, variante), MPol 18:2. — DELG, s.v. δοκάω etc., III, p. 291. M-M. TW. Spicq. Sv.</p></div></section></article> <article id=\"entry-dokos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δοκός, οῦ, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dokós⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Ver δέχομαι; Homero e outros; inscrições, papiros, LXX; Josefo, Bell. 3, 214s.; Ant. 14, 106; empréstimo no hebraico rabínico.) <strong>Peça de madeira pesada, como uma viga usada na construção de telhados ou para trancar uma porta: viga, trave.</strong> Mt 7:3ss.; Lc 6:41s. (cf. Ox 1, verso, 1–4). — GKing, HTR 17, 1924, 393–404; 26, 1933, 73–76; CWebster, ET 39, 1928, 91s.; PHedley, ibid. 427s.; SKaatz, Jeschurun 16, 1929, 482–484. — B. 599. DELG, s.v. δέχομαι. M-M.</div></section></article> <article id=\"entry-dolios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δόλιος, ία, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dólios⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Ver os quatro verbetes seguintes; Homero e outros; LXX; TestSol 26:5 B; Josefo, Bell. 4, 208; Ant. 1, 335.) <strong>Relativo à violação da confiança com intenção de enganar: enganoso, fraudulento, traiçoeiro.</strong> ἐργάται δ., «trabalhadores desonestos», 2Co 11:13; χείλη δ., «lábios enganosos», 1Cl 15:5 (Sl 30:19; 11:4). Com κατάλαλος, οἱ δ., «pessoas traiçoeiras» (cf. Sir 11:29), Hs 9, 26, 7. — DELG, s.v. δόλο. M-M.</div></section></article> <article id=\"entry-doliotes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δολιότης, ητος, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦doliótēs⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Vécio Valente 2, 3; LXX; Test12Patr.) <strong>Engano, traição.</strong> περιπλέκειν δολιότητα, «tramar engano», 1Cl 35:8 (Sl 49:19). Com πονηρία, Hs 8, 6, 2. — DELG, s.v. δόλο.</div></section></article> <article id=\"entry-dolioo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δολιόω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dolióō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Imperfeito, terceira pessoa do plural: ἐδολιοῦσαν; B-D-F §84, 3; Mlt-H. 195; Rdm.² 92, 95 (escólio a Sófocles, Trach. 412, p. 303 P.; LXX). <strong>Enganar.</strong> Rm 3:13 (Sl 5:10; 13:3). — DELG, s.v. δόλο.</div></section></article> <article id=\"entry-dolos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δόλος, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dólos⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Ver os três verbetes anteriores e δολόω; Homero e posteriores; inscrições, papiros, LXX; PsSol 4:8; Test12Patr; ApcEl [PSI 7, verso, 3]; SibOr 3, 191; EpArist 246; Fílon; Josefo, C. Ap. 2, 200 e outros; Justino, D. 14, 2; Irineu 5, 29, 2 [Harv. II, 404, 2]; empréstimo no hebraico rabínico.) <strong>Obter vantagem por artifícios e métodos dissimulados: engano, astúcia, traição.</strong> Nas seguintes listas de vícios (cf. Herm. Wr. 13, 7b), δ. pode ser traduzido por «engano»: Mc 7:22; Rm 1:29; D 5:1; B 20:1; plural, 1Cl 35:5. ἐν ᾧ δ. οὐκ ἔστιν, «em quem não há falsidade alguma» (Teógnis 416, πιστὸν ἑταῖρον, ὅτῳ μή τις ἔνεστι δόλος; LXX), Jo 1:47; cf. 1Pe 2:22; 1Cl 16:10 (ambos Is 53:9); 50:6; Ap 14:5, variante (ambos Sl 31:2); Pol 8:1 (segundo 1Pe 2:22). πλήρης παντὸς δ., «monstro de dissimulação» (Goodsp.), At 13:10 (Justino, D. 14, 2, μεμεστωμένοι … δόλου). Com κακία, 1Pe 2:1 (FDanker, ZNW 58, 1967, 93–95); λαλεῖν δ., «falar com engano», 1Pe 3:10; 1Cl 22:3 (ambos Sl 33:14). — δόλῳ, «com astúcia ou às ocultas» (Homero e outros; Êx 21:14; Dt 27:24 e outros; ViAhiae [Ahijah] 3 [p. 92, 2 Sch.]; Fílon, Spec. Leg. 4, 183; Josefo, Ant. 10, 164; orações de vingança de Reneia: SIG 1181, 3 e Dssm., LO 352; 354ss. [LAE 423ss.]; cf. μετὰ δόλου, Did., Gen. 126, 20), Mt 26:4; 2Co 12:16. δόλῳ πονηρῷ, «com astúcia perversa» (SIG 693, 2; 5; cf. 9; OGI 629, 112; BGU 326 II, 3 [Hunt-Edgar 85 II, 3]), IEph 7:1. Também ἐν δ. (Sófocles, Phil. 102; Sb 14:30; 1Mac 1:30), Mc 12:14, variante; 14:1; 1Ts 2:3. — B. 1171. DELG. M-M. TW.</div></section></article> <article id=\"entry-doloo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δολόω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dolóō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Ver os quatro verbetes anteriores.) Primeiro aoristo ἐδόλωσεν, Sl 14:3; 35:2 (Hesíodo, Heródoto e outros; Vécio Valente 248, 2; SIG 1168, 102). Em geral, «seduzir mediante ardil»; daí, <strong>tornar falso mediante engano ou distorção: falsificar, adulterar</strong> (assim Dioscórides 1, 67; 68 W.; Luciano, Hermot. 59, τὸν οἶνον, «o vinho»; PLeid X, v, 37; xii, 2 [papiro químico]), 1Co 5:6, códice D; δ. τὸν λόγον τοῦ θεοῦ, «adulterar a palavra de Deus», 2Co 4:2. — DELG, s.v. δόλο. M-M.</div></section></article> <article id=\"entry-doma-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δόμα, δόματος, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dóma⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Pseudo-Platão, Defin. 415b; Plutarco; papiros [Mayser 435]; LXX; EpArist 224; Fílon, Cher. 84; Justino, D. 39, 2 e outros. Cf. o verbete δῶμα.) <strong>Dádiva, presente.</strong> δ. ἀγαθά, «boas dádivas» (cf. Sir 18:17), Mt 7:11; Lc 11:13. διδόναι δόματά τινι, «dar presentes a alguém», Ef 4:8 (cf. Sl 67:19; Justino, D. 39, 4); οὐχ ὅτι ἐπιζητῶ τὸ δ., «não que eu procure o presente», Fp 4:17. — DELG, s.v. δίδωμι A. M-M.</div></section></article> <article id=\"entry-doxa-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δόξα, ης, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dóxa⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Ver δοξάζω; diversos sentidos desde Homero; em Ath., «significado».) Em muitas passagens desta literatura, as concepções veterotestamentárias e greco-romanas da dependência da fama e da honra em relação a feitos extraordinários merecem exploração adicional. SIG 456, 15 é típico: a preocupação pelos outros eleva a δόξα, isto é, a reputação de alguém. O uso comum do grego δ. no sentido de «noção, opinião» não ocorre no NT.\n<p><strong>① Estado de ser luminoso ou resplandecente: brilho, esplendor, fulgor</strong> (aspecto característico do hebraico כָּבוֹד).\n<strong>ⓐ De fenômenos físicos</strong> (PGM 13, 189, τὴν δόξαν τοῦ φωτός; cf. 298ss.; Rtzst., <i>Mysterienrel.</i>³, 357ss.; também 314, δόξα ἐκ τ. πυρός [cf. Justino, D. 128]; 315, φῶς κ. δόξαν θεῖαν [= Cleópatra 150]; LXX; TestJob 43:6, τῆ λαμπάδα αὐτοῦ): οὐκ ἐνέβλεπον ἀπὸ τῆς δ. τοῦ φωτός, «não podia enxergar devido ao brilho da luz», At 22:11; ὁρᾶν τὴν δ., «ver o fulgor», Lc 9:32; cf. v. 31. Tudo no céu possui esse esplendor: os corpos luminosos celestes, 1Co 15:40s. (cf. PGM 13, 64, σὺ ἔδωκας ἡλίῳ τὴν δόξαν κ. δύναμιν; 448; Sir 43:9, 12; 50:7).\n<strong>ⓑ De seres humanos em circunstâncias transcendentes e de seres transcendentes</strong>: querubins (Sir 49:8; Ez 10:4), Hb 9:5; anjos, Lc 2:9; Ap 18:1. Especialmente do próprio Deus (Êx 24:17; 40:34; Nm 14:10; Bar 5:9, τὸ φῶς τῆς δόξης αὐτου; Tb 12:15; 13:16 BA; 2Mac 2:8; SibOr 5, 427): ὁ θεὸς τῆς δ., «Deus da glória» (En 25:7), At 7:2 (Sl 28:3); cf. Jo 12:41 (Is 6:1); At 7:55; 2Ts 1:9; 2Pe 1:17b; Ap 15:8; 19:1; 21:11, 23. ὁ πατὴρ τῆς δ., «Pai da glória», Ef 1:17; βασιλεὺς τῆς δ., «Rei da glória», AcPl BMM, verso, 24 e 26. Também dos que comparecem diante de Deus: Moisés, 2Co 3:7–11, 18 (Justino, D. 127, 3; cf. Ἀδὰμ τῆς δ. θεοῦ ἐγυμνώθη, GrBar 4:16); cristãos na vida futura, 1Co 15:43; Cl 3:4. δόξα τοῦ θεοῦ em relação ao juízo final, Rm 3:23; 5:2 (mas ver ③); Jesus possui σῶμα τῆς δ., «corpo radiante, glorioso», Fp 3:21; cf. 2Cl 17:5; Cristo é κύριος τ. δόξης, «Senhor da glória», 1Co 2:8 (cf. En 22:14; 27:3, 5; 36:4; 40:3, de Deus; PGM 7, 713, κύριοι δόξης, de divindades). — O conceito estendeu-se para denotar <strong>glória, majestade, sublimidade de Deus</strong> de maneira geral (PGM 4, 1202, ἐφώνησά σου τ. ἀνυπέρβλητον δόξαν; Orígenes, C. Cels. 4, 1, 24, οἰκοδομεῖν … ναὸν δόξης θεοῦ): ἀλλάσσειν τὴν δ. τοῦ θεοῦ, «trocar a majestade de Deus», Rm 1:23; κατενώπιον τῆς δόξης αὐτοῦ, «diante de sua glória», isto é, «diante dele próprio», Jd 24 (cf. En 104:1). Cristo foi ressuscitado dentre os mortos διὰ τῆς δ. τοῦ πατρός, «pela majestade do Pai» (aqui, como em Jo 2:11, também se faz presente a ideia de poder, força; cf. Rtzst., <i>Mysterienrel.</i>³, 344, 359; PGM 4, 1650, δὸς δόξαν καὶ χάριν τῷ φυλακτηρίῳ τούτῳ; Sb 9:11, φυλάξει με ἐν τ. δόξῃ; Fílon, Spec. Leg. 1, 45; JVogel, <i>Het sanscrit woord tejas [=gloedvuur] in de beteekenis van magische Kracht</i>, 1930), Rm 6:4; cf. Mt 16:27; Mc 8:38; AcPl Ha 10, 9. ὄψῃ τὴν δ. τοῦ θεοῦ, «verás a glória de Deus», Jo 11:40; κράτος τῆς δ., «poder majestoso», Cl 1:11; πλοῦτος τῆς δ., «riqueza de sua glória», Rm 9:23; Ef 1:18; cf. Ef 3:16; Fp 4:19; Cl 1:27; δ. τῆς χάριτος, «glória de sua graça» (PGM 4, 1650), Ef 1:6; com ἀρετή, 2Pe 1:3 (τῆς ἐπ’ ἀρετῇ καὶ δόξῃ διαλήψεως, inscrição de Afrodisias II, 14: ZPE 8, 1971, 186); ἀπαύγασμα τῆς δ., «resplendor da glória», Hb 1:3; τὴν ἐπιφάνειαν τῆς δ. τοῦ μεγάλου θεοῦ, «a manifestação da glória do grande Deus», Tt 2:13. Alguns classificariam Rm 2:7, 10 aqui, mas essas passagens e outras com δόξα καὶ τιμή pertencem provavelmente a ③, por seu enfoque na honra e no prestígio. Doxologia: σοῦ ἐστιν ἡ δ. εἰς τ. αἰῶνας, ἀμήν, «tua é a glória pelos séculos, amém» (Odes 12:15 [Oração de Manassés]), Mt 6:13, variante; AcPl Ha 2, 33; εἰς ἔπαινον τῆς δ. αὐτοῦ, «para louvor de sua glória», Ef 1:12, 14; cf. 1:6. — 1Ts 2:12; 1Pe 5:10. Plural, Hv 1, 3, 3. κατὰ τὸ εὐαγγέλιον τῆς δ. τοῦ μακαρίου θεοῦ, «segundo o evangelho da glória do Deus bendito», 1Tm 1:11. Transferido a Cristo: Mt 19:28; 24:30; 25:31; Mc 10:37; 13:26; Lc 9:26; 21:27; Jo 1:14; 2:11; Tg 2:1 (AMeyer, <i>D. Rätsel d. Js</i>, 1930, 118ss.); B 12:7; AcPl Ha 7:7. τὸν φωτισμὸν τοῦ εὐαγγελίου τῆς δ. τοῦ χριστοῦ, «a mensagem que resplandece com a grandeza de Cristo», 2Co 4:4; cf. 4:6 (Justino, A I, 51, 8, παραγίνεσθαι μετὰ δόξης μέλλει). Do prestígio de Cristo promovido pelos companheiros de Paulo, 2Co 8:23 (mas ver ①ⓓ e ③).\n<strong>ⓒ A condição da vida futura</strong> é descrita, assim, como participação no esplendor ou na glória. <strong>α. Com referência a Cristo</strong>: εἰσελθεῖν εἰς τὴν δ. αὐτοῦ, «entrar em sua glória», Lc 24:26 (βασιλείαν em P⁷⁵, primeira mão); ἀνελήμφθη ἐν δ., «foi recebido em glória», 1Tm 3:16; cf. τὰς μετὰ ταῦτα δ., «as glórias posteriores», 1Pe 1:11 (mas ver β; plural por causa de παθήματα; cf. Sb 18:24; Isócrates 4, 51; POslo 85, 13 [séc. III d.C.]), 21; ἐν τῇ ἀποκαλύψει τῆς δ. αὐτοῦ, «na revelação da sua glória», 1Pe 4:13. Também da preexistência de Cristo: Jo 17:5, 22, 24. <strong>β. Com referência aos seus seguidores</strong> (cf. Dn 12:13; Herm. Wr. 10, 7): Rm 8:18, 21; 1Co 2:7; 2Co 4:17; 1Ts 2:12; 2Ts 2:14; 2Tm 2:10; Hb 2:10; 1Pe 5:1, 4 (στέφανος τ. δόξης, «coroa de glória»; cf. Jr 13:18; TestBenj 4:1); εἰς … δ. καὶ τιμὴν ἐν ἀποκαλύψει Ἰησοῦ Χριστοῦ, «para glória e honra na revelação de Jesus Cristo», 1Pe 1:7 (talvez 1:11 também pertença aqui, com referência aos sofrimentos suportados por Cristo); πνεῦμα τῆς δ., com πν. τοῦ θεοῦ, 1Pe 4:14; ἵνα πνευματικὴν καὶ ἄφθαρτον τῆς δικαιοσύνης δόξαν κληρονομήσωσιν, «para herdarem a glória espiritual e incorruptível da justiça», final de Mc 16:14, variante (manuscrito Freer, linhas 11s.; Cleópatra 146s., ἐνέδυσεν αὐτοὺς θείαν δόξαν πνευματικήν); ἥτις ἐστὶν δ. ὑμῶν, «[minhas tribulações] promovem vossa glória», Ef 3:13 (ver MDibelius, comentário a Cl 1:24ss.); τόπος τῆς δ., «lugar da glória», isto é, «o além», 1Cl 5:4.\n<strong>ⓓ Brilho refletido: reflexo.</strong> ἀνὴρ … εἰκὼν καὶ δόξα θεοῦ, «o homem [em distinção da mulher] é imagem e reflexo de Deus», 1Co 11:7 (talvez esse pensamento se exprima em Rm 3:23; 5:2, mas ver ③); também γυνὴ δόξα ἀνδρός, «a mulher é glória do homem», no mesmo versículo (cf. semelhança formal, mas sentido diferente, na inscrição judaica citada por Lietzmann, comentário ao lugar: ἡ δόξα Σωφρονίου Λούκιλλα εὐλογημένη; ver AFeuillet, RB 81, 1974, 161–182). Alguns interpretam δ. Χριστοῦ em 2Co 8:23 como referência aos colaboradores de Paulo (mas ver ①ⓑ).</p>\n<p><strong>② Condição de grande magnificência: grandeza, esplendor, tudo que chama a atenção</strong> (1Esd 6:9; 1Mac 10:60, 86; 2Mac 5:20): vestimentas suntuosas (Sir 6:31; 27:8; 45:7; 50:11), de um rei, Mt 6:29; Lc 12:27; esplendor régio em geral (Bar 5:6; 1Mac 10:58; Josefo, Ant. 8, 166), Mt 4:8; Lc 4:6; Ap 21:24, 26. Esplendor humano de qualquer espécie, 1Pe 1:24 (Is 40:6).</p>\n<p><strong>③ Honra como elevação ou reconhecimento de condição ou realização: fama, reconhecimento, renome, honra, prestígio.</strong> (Ver ἀγαθός e verbetes δικαιο-; Diodoro Sículo 15, 61, 5, δόξα em uso absoluto = «boa reputação»; Apiano, Bell. Civ. 2, 89 §376, δ. ἀγαθή, «boa reputação, estima»; Polieno 8, prólogo, δόξα ἀθάνατος, «renome eterno»; Herm. Wr. 14, 7; PsSol 1:4; 17:6; Josefo, Ant. 4, 14; Vi. 274; Justino, A II, 10, 8, δόξης … καταφρονήσαντος.) Da aprovação pública (cf. Orígenes, C. Cels. 7, 24, 1; Did., Gen. 238, 25), ἐνώπιον πάντων τῶν συνανακειμένων σοι, «diante de todos os que estão reclinados contigo», Lc 14:10; δ. λαμβάνειν, «receber glória» (En 99:1; Diógenes Laércio 9, 37, de Demócrito, οὐκ ἐκ τόπου δόξαν λαβεῖν βουλόμενος), Jo 5:41, 44a e outros; de modo semelhante, Deus e o Cordeiro recebem honra, Ap 4:11; 5:12. Jo 8:54 («fazer elevadas reivindicações acerca de mim mesmo»); 12:43a (cf. 8:50); Rm 9:4; 2Co 6:8 (oposto a ἀτιμία); 1Ts 2:6; 1Cl 3:1; B 19:3; Hv 1, 1, 8. Em geral, γυνὴ … ἐὰν κομᾷ, δόξα αὐτῇ ἐστιν, «se a mulher tem cabelos longos, isso lhe confere reputação favorável», 1Co 11:15 (oposto a ἀτιμία). Oxímoro: ὧν … ἡ δόξα ἐν τῇ αἰσχύνῃ αὐτῶν, «cujo prestígio reside na própria vergonha», Fp 3:19. Da elevação do prestígio divino como objetivo, Jo 7:18; a enfermidade de Lázaro reverte em honra para Deus, Jo 11:4; Rm 15:7. Da aprovação divina de pessoas, δ. τοῦ θεοῦ, Jo 5:44b; 12:43b (cf. 1QH 17:15; 1QS 4:23); Rm 3:23; 5:2. Também aqui pertencem as passagens com δόξα καὶ τιμή / τιμὴ καὶ δόξα, «glória e honra» (LXX; inscrições, p.ex. OGI 223, 12; 244, 19s.; 763, 37; Welles 42, 6; PGM 4, 1616s., δὸς δ. καὶ τιμὴν κ. χάριν; Justino, D. 42, 1), Rm 2:7, 10; 1Tm 1:17; Hb 2:7, 9 (Sl 8:6); cf. Hb 3:3; 1Pe 1:7; 2Pe 1:17; Ap 4:9, 11; 5:12, 13; 21:26. De pessoas que conferem renome por sua excelência: Jesus, Lc 2:32 (cf. Rm 9:4); destinatários das cartas de Paulo, ὑμεῖς ἡ δ. ἡμῶν, «vós sois o nosso renome», 1Ts 2:20 (cf. inscrição judaica em Lietzmann, ①ⓓ: Lucila confere renome a Sofrônio).\n— A liturgia israelita fornece o modelo para a fórmula litúrgica δ. θεῷ, «glória é» (BWeiss; HHoltzmann; Harnack; Zahn; EKlostermann; ASchlatter; Rengstorf) ou «seja dada» (Weizsäcker; JWeiss; OHoltzmann) «a Deus», Lc 2:14. Cf. 19:38; Rm 11:36; 16:27; Gl 1:5; Ef 3:21; Fp 4:20; 2Tm 4:18 (talvez Cristo seja o referente); Hb 13:21; 1Pe 4:11; 1Cl 20:12; 50:7 e outros; τιμὴ καὶ δ., «honra e glória», 1Tm 1:17 (ver também formulação extrabíblica acima, especialmente OGI 223, 12; 244, 19s.; 763, 37); cf. Jd 25, variante; Ap 5:13; 7:12. Doxologias dirigidas a Cristo, 2Pe 3:18; Ap 1:6; εἰς (τὴν) δ. (τοῦ) θεοῦ, «para o louvor de Deus», Rm 15:7; 1Co 10:31; 2Co 4:15; Fp 1:11; 2:11; cf. Rm 3:7; também πρὸ δ., 2Co 1:20; πρὸ τὴν αὐτοῦ τοῦ κυρίου [Cristo] δ., 2Co 8:19. Daí a expressão δ. διδόναι τῷ θεῷ, «louvar a Deus» (Bar 2:17s.; 1Esd 9:8; 4Mac 1:12): em ação de graças, Lc 17:18; Ap 19:7; como forma de devoção religiosa, At 12:23; Rm 4:20; Ap 4:9; 11:13; 14:7; 16:9; como adjuração, δὸς δ. τῷ θεῷ, «dá louvor a Deus dizendo a verdade», Jo 9:24.\n— GBoobyer, «Thanksgiving» and the «Glory of God» in Paul, diss., Leipzig, 1929; LChampion, <i>Benedictions and Doxologies in the Epistles of Paul</i>, 1935; MPamment, «The Meaning of δόξα in the Fourth Gospel», ZNW 74, 1983, 12–16: a glória de Deus manifesta-se mediante a dádiva da entrega voluntária de Jesus na cruz.</p>\n<p><strong>④ Ser transcendente digno de honra: ser majestoso</strong>, por metonímia (cf. Diodoro Sículo 15, 58, 1, de cidadãos que se destacavam dos outros em ἐξουσίαι καὶ δόξαι, «cargos e honras»), de seres angélicos (ver Fílon, Spec. Leg. 1, 45; PGM 1, 199): δόξαι, «seres [celestiais] majestosos», Jd 8; 2Pe 2:10 (ver também Êx 15:11 LXX; TestJud 25:2, αἱ δυνάμεις τ. δόξης; também o texto mágico em Rtzst., <i>Poim.</i> p. 28 [VI 17], χαιρέτωσάν σου αἱ δόξαι [praticamente = δυνάμει] εἰς αἰῶνα, κύριε). Cf. JSickenberger, <i>Engels- oder Teufelslästerer?</i>, Festschrift zur Jahrhundertfeier der Universität Breslau, 1911, 621ss. É também provável o sentido «majestades» e, por metonímia, «pessoas ilustres».</p>\n<p>Sobre o vocábulo em geral: Rtzst., <i>Mysterienrel.</i>³, 289; 314s.; 344; 355ss.; AvGall, <i>D. Herrlichkeit Gottes</i>, 1900; IAbrahams, <i>The Glory of God</i>, 1925; AForster, «The Meaning of Δόξα in the Greek Bible», ATR 12, 1929/30, 311ss.; EOwen, «Δόξα and Cognate Words», JTS 33, 1932, 139–150; 265–279; CMohrmann, «Note sur doxa», <i>ADebrunner Festschrift</i>, 1954, 321–328; LBrockington, «LXX Background to the NT Use of δ.», <i>Studies in the Gospels in Memory of RLightfoot</i>, 1955, 1–8; HBöhlig, <i>D. Geisteskultur v. Tarsos</i>, 1913, 97ss.; GWetter, <i>D. Verherrlichung im Joh.-ev.</i>, Beiträge zur Religionswissenschaft II, 1915, 32–113; <i>Phos</i>, 1915; RLloyd, «The Word 'Glory' in the Fourth Gospel», ET 43, 1932, 546–548; BBotte, «La gloire du Christ dans l'Evangile de S. Jean», <i>Questions liturgiques</i> 12, 1927, 65ss.; HPass, <i>The Glory of the Father: A Study in St John 13–17</i>, 1935; WThüsing, <i>Die Erhöhung u. Verherrlichung Jesu im J</i>, 1960; GKittel, <i>D. Rel.-gesch. u. d. Urchristentum</i>, 1932, 82ss.; JSchneider, <i>Doxa</i>, 1932; HKittel, <i>D. Herrlichkeit Gottes</i>, 1934; MGreindl, <i>Κλεος, Κυδος, Ευχος, Τιμη, Φατις, Δοξα</i>, diss., Munique, 1938; AVermeulen, <i>Semantic Development of Gloria in Early-Christian Latin</i>, 1956; RAC IV, 210–216; XI, 196–225. — B. 1144s.; DELG, s.v. δοκάω etc., II, p. 291; Schmidt, <i>Syn.</i> I, 321–328, ver δοκέω; M-M. EDNT. TW. Spicq. Sv.</p></div></section></article> <article id=\"entry-doxazo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δοξάζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦doxázō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Ver δόξα.) Imperfeito ἐδόξαζον; futuro δοξάσω; primeiro aoristo ἐδόξασα, imperativo δόξασον; perfeito, primeira pessoa do plural, δεδοξάκαμεν (Justino, D. 1:4). Na passiva: primeiro aoristo ἐδοξάσθην; perfeito δεδόξασμαι, Jo 17:10 (Xenófanes e trágicos e posteriores; LXX; pseudoepígrafos; Fílon; Josefo; Mel., P. 92, 692; Justino e Ath., frequentemente no sentido de «exprimir uma opinião»).\n<p><strong>① Influenciar a opinião sobre alguém de modo a elevar-lhe a reputação: louvar, honrar, exaltar.</strong> (Tucídides 3, 45, 4; Políbio 6, 53, 10, δεδοξασμένοι ἐπ’ ἀρετῃ; OGI 168, 56 [115 a.C.]; cf. ViJer 2 [Sch. 71, 5]; LXX; EpArist; Josefo, Ant. 4, 183.) Com τινά, «alguém», Mt 6:2; a si mesmo, Ap 18:7 (cf. ②); o Pai, Mt 5:16; Deus (SibOr frag. 1, 21), Mt 9:8; 15:31; Mc 2:12; Lc 5:25s.; 7:16; 13:13; 17:15; 18:43; 23:47; At 11:18; 21:20; Rm 15:6, 9; 1Pe 2:12; MPol 14:3; 19:2; AcPl Ha 6, 13; τ. κύριον, AcPl Ha 20:1; Hv 3, 4, 2; AcPl Ha 7, 24 (δόξαι no papiro, talvez = δοξάσαι). ἔν τινι, «na pessoa de alguém», Gl 1:24 (FNeugebauer, <i>In Christus</i> etc., 1961, 43); cf. 1Co 6:20; ἐν τῷ ὀνόματι (μέρει, variante) τούτῳ, «neste nome» (o de cristão), 1Pe 4:16; κατὰ δὲ ὑμᾶς δοξάζεται, «entre vós o Espírito de Deus é honrado», 1Pe 4:14, variante. ἐπί τινι, «por causa de algo» (com αἰνεῖν), Lc 2:20 (ver Políbio acima); At 4:21; διά τινος e ἐπί τινι, 2Co 9:13; διὰ Ἰησοῦ Χριστοῦ, «por meio de Jesus Cristo», 1Pe 4:11. Com εὐχαριστεῖν, Rm 1:21 (o pecado capital é não agradecer os benefícios recebidos; a reciprocidade exige glorificar o benfeitor, daí as frequentes referências nas inscrições ao reconhecimento dos benefícios, p.ex. IPriene 3, 26s.; 6, 24–27). O nome (Nicolau de Damasco, 90 frag. 19 Jac. [em Josefo, Ant. 1, 160], τοῦ Ἀβράμου ἔτι κ. νῦν τὸ ὄνομα δοξάζεται, «o nome de Abraão é reverenciado ainda hoje») de Deus, Ap 15:4 (Sl 85:9); Hv 2, 1, 2; 3, 4, 3 (Justino, D. 41, 3); τὸ ὄνομα, «o nome», isto é, o nome de Deus, IPhld 10:1 (cf. POxy 924, 13, ἵνα τὸ ὄνομά σου ᾖ διὰ παντὸς δεδοξασμένον; PGM 36, 165). De Cristo, Lc 4:15; IEph 2:2; ISm 1:1; Pol 8:2; τόν σε λυτρωσάμενον ἐκ θανάτου, «aquele que te resgatou da morte», B 19:2; o amor de alguém, IPol 7:2. Absoluto = «louvar a Deus», ITr 1:2. τὴν διακονίαν μου δοξάζω, «glorio-me em meu ministério» ou «levo a sério minha incumbência», Rm 11:13. — δοξάζεται μέλος, «um membro é honrado», 1Co 12:26; δοξασθεὶς μεγάλως, «recebendo grandes honras», 1Cl 17:5.</p>\n<p><strong>② Conferir esplêndida grandeza, revestir de esplendor: glorificar</strong>, da glória que procede da vida futura (ver δόξα ①ⓒ), At 3:13 (cf. Is 52:13); Rm 8:30; B 21:1; Jo 7:39; 12:16, 23, 28; 13:31, 32; 17:1, 5, 10. É termo predileto de João (ver Thüsing e outros, s.v. δόξα, final), em cujo relato toda a vida de Jesus é apresentada como glorificação do Filho pelo Pai: Jo 8:54; 12:28; 13:31; 17:1, 4 (cf. GCaird, NTS 15, 1968/69, 265–277); simultaneamente, como glorificação do Pai pelo Filho: Jo 13:31s.; 14:13; 17:1. A glorificação do Filho realiza-se pelos milagres que o Pai lhe concede realizar, Jo 11:4 (cf. PGM 7, 501ss., κυρία ῏Ισις, δόξασόν με, ὡς ἐδόξασα τὸ ὄνομα τοῦ υἱοῦ σου ῟Ωρος; IAndrosIsis, Kyme 40 [ver também comentário de Peek, p. 63], dito pela divindade: οὐδεὶς δοξάζεται ἄνευ τ. ἐμῆς γνώμης); pela atuação do Paráclito, Jo 16:14; e pelos «seus», Jo 17:10, que também glorificam o Pai, Jo 15:8, especialmente no martírio, Jo 21:19 (sobre δοξάζεσθαι ἐν em Jo 13:31s.; 14:13; 15:8; 17:10, cf. Diodoro Sículo 12, 36, 2; 16, 82, 7, ἐν συνέσει δεδοξασμένος; Sir 48:4; 1Mac 2:64). — 2Co 3:10; τὸν λόγον τοῦ κυρίου, «a palavra do Senhor», At 13:48; cf. 2Ts 3:1; B 6:16 (Is 49:5); IPol 8:1. χαρὰ δεδοξασμένη, «alegria cheia de glória», 1Pe 1:8; Pol 1:3. οὐχ ἑαυτὸν ἐδόξασεν γενηθῆναι ἀρχιερέα, «não atribuiu a si mesmo o prestígio do sumo sacerdócio», Hb 5:5. — Quanto a Ap 18:7, ver ①. δοξάζοντες, Jo 11:31, variante. Bibliografia, ver δόξα, final; também ESelwyn, <i>First Epistle of Peter</i>, 1946, 253–258. — DELG, s.v. δοκάω etc., II, p. 291. M-M. TW. Spicq. Sv.</p></div></section></article> <article id=\"entry-doxologia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δοξολογία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦doxología⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Sobre o prefixo δοξο-, ver DELG, s.v. δοκάω etc., II, p. 291; Orígenes, De Or. 14, 2, p. 331, 6 e outros lugares na literatura patrística; Jâmblico, Myst. 2, 10; TestAbr A 20, p. 103, 29 [Stone, p. 54].) <strong>Cântico de louvor, oração.</strong> ἐν τῇ ὥρα τῆς δ. αὐτοῦ, «na hora da sua oração», GJs 13:1.</div></section></article> <article id=\"entry-dorkas-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Δορκάς, άδος, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Dorkás⟧</span><span class=\"separator\">·</span><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Eurípides, Heródoto e outros; papiros, LXX; Test12Patr.) <strong>Dorcas</strong>, nome que significa «gazela», traduzindo outro nome (ver Ταβιθά), At 9:36, 39 (Δορκάς como nome próprio, por exemplo, em Josefo, Bell. 4, 145; Luciano, Dial. Meretr. 9; SIG² 854, 11; 12; 23; IG VII, 942; XIV, 646). Goodsp., <i>Problems</i>, 130. — DELG. M-M.</div></section></article> <article id=\"entry-dory-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δόρυ, ρατος, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dóry⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Homero e outros; inscrições; LXX; JosAs 26:7; SibOr 4, 63; Josefo, Bell. 5, 313; Ant. 6, 187; Taciano 2, 2; empréstimo no hebraico rabínico.) Originalmente, <strong>árvore ou parte de uma árvore usada para tábuas, mastros ou hastes de lanças</strong>; depois, <strong>lança</strong>, na descrição do armamento de uma pessoa íntegra, IPol 6:2. — B. 48; 1390. DELG.</div></section></article>"};
